"""Design Linked List — singly linked list with a sentinel head.

The sentinel removes every "is this the first node?" special case.

Time: O(index) per operation   Space: O(n)
"""


class _Node:
    __slots__ = ("val", "next")

    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


class MyLinkedList:
    def __init__(self):
        self._head = _Node()       # sentinel
        self._size = 0

    def _node_before(self, index: int) -> _Node:
        node = self._head
        for _ in range(index):
            node = node.next
        return node

    def get(self, index: int) -> int:
        if index < 0 or index >= self._size:
            return -1
        return self._node_before(index).next.val

    def addAtHead(self, val: int) -> None:
        self.addAtIndex(0, val)

    def addAtTail(self, val: int) -> None:
        self.addAtIndex(self._size, val)

    def addAtIndex(self, index: int, val: int) -> None:
        if index > self._size:
            return
        index = max(index, 0)
        prev = self._node_before(index)
        prev.next = _Node(val, prev.next)
        self._size += 1

    def deleteAtIndex(self, index: int) -> None:
        if index < 0 or index >= self._size:
            return
        prev = self._node_before(index)
        prev.next = prev.next.next
        self._size -= 1
